package pzvrphysicality;
import java.util.*;import org.joml.Matrix4f;import org.joml.Vector3f;
/** Authored native producer receipts, never an original game drawer or XR entrypoint. */
public final class NativeHeldFallbackTest {
 private static int checks;private static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
 private static float[] array(Matrix4f value){return value.get(new float[16]);}
 private static boolean same(Matrix4f a,Matrix4f b){return a.equals(b,.0002f);}
 private static void rejects(Runnable action,String why){boolean rejected=false;try{action.run();}catch(IllegalArgumentException expected){rejected=true;}check(rejected,why);}
 private static float[] packet(Matrix4f model,int count){float[] rows=new float[count*68];for(int n=0;n<count;n++){model.get(rows,n*68);model.get(rows,n*68+36);rows[n*68+24]=1;rows[n*68+25]=2;rows[n*68+26]=3;rows[n*68+27]=.7f;rows[n*68+16]=.11f;rows[n*68+28]=.44f;rows[n*68+52]=.88f;}return rows;}
 private static final class Authored implements NativeHeldFallback.Adapter {
  Object frame=new Object(),actor=new Object(),input=new Object(),scene=new Object(),skin=new Object(),item=new Object();long receipt;boolean current=true,eligible=true,ready=true,validDrawer=true;int calls,discards;NativeHeldFallback.Drawer drawer;
  Matrix4f[] output={new Matrix4f().translation(1,2,3),new Matrix4f().translation(4,5,6)};
  public NativeHeldFallback.Capture begin(Object f,Object slot,Object a,long epoch){return f==frame&&a==actor?new NativeHeldFallback.Capture(frame,actor,input,scene,skin,array(new Matrix4f().translation(10,20,30).scale(-1.5f,1.5f,1.5f)),0,1,List.of(new NativeHeldFallback.Slot(0,item)),System.nanoTime(),receipt,null):null;}
  public boolean current(NativeHeldFallback.Capture capture){return current&&capture.frame()==frame&&capture.actor()==actor&&capture.input()==input&&capture.scene()==scene&&capture.skin()==skin;}
  public long receipt(){return receipt;}
  public boolean eligible(NativeHeldFallback.Capture c,NativeHeldFallback.Slot slot){return eligible&&slot.item()==item;}
  public NativeHeldFallback.Drawer draw(NativeHeldFallback.Capture c,NativeHeldFallback.Slot slot){calls++;if(!ready)return null;var world=NativeHeldMount.world(100,200,300.002f,100,200,300,0,0,0);var model=new Matrix4f(world).mul(new Matrix4f().rotationX(.2f).scale(.4f));drawer=new NativeHeldFallback.Drawer(1,2,packet(model,2),new int[]{71,15},new int[]{-1,-1},new int[]{-1,-1},array(world),new Object());return drawer;}
  public boolean drawerCurrent(NativeHeldFallback.Capture c,NativeHeldFallback.Slot slot,NativeHeldFallback.Drawer d){return validDrawer&&d==drawer;}
  public void discard(NativeHeldFallback.Capture c,NativeHeldFallback.Drawer d){discards++;}
  void capture(){NativeHeldFallback.begin(frame,new Object(),actor);NativeHeldFallback.fingers(skin,output);receipt=System.nanoTime();NativeHeldFallback.end(null);}
 }
 private static Authored setup(){var a=new Authored();NativeHeldFallback.adapterForTest(a);NativeHeldFallback.configureForTest(true);return a;}
 private static void math(){
  check(same(NativeHeldMount.world(11,22,3.5f,10,20,3,0,0,0),new Matrix4f().translation(-1,1.2247448f,-2).scale(-1.5f,1.5f,1.5f)),"copied native world-axis/camera/1.5-unit placement numeric oracle");
  var actor=new Matrix4f().translation(10,20,30).scale(-.015f,.015f,.015f).rotateY(.3f);var prop=new Matrix4f().translation(30,40,50).rotateX(.2f);float[] aa=array(actor),pp=array(prop),savedA=aa.clone(),savedP=pp.clone();var socket=NativeHeldMount.socket(aa,pp);var original=new Matrix4f(actor).mul(prop);
  check(socket.getTranslation(new Vector3f()).equals(original.getTranslation(new Vector3f()),.0001f),"actual socket translation retains actor and skeletal units");check(Math.abs(socket.determinant()+1)<.001,"native actor reflection retained once");check(Arrays.equals(aa,savedA)&&Arrays.equals(pp,savedP),"source actor and Prop matrices immutable");
  var world=NativeHeldMount.world(100,200,300.00175f,100,200,300,15,25,35);var local=new Matrix4f().translation(.05f,.06f,.07f).rotateZ(.4f).scale(.4f);var source=new Matrix4f(world).mul(local);var correction=NativeHeldMount.correction(aa,pp,array(world));var mounted=new Matrix4f(correction).mul(source);var expected=new Matrix4f(socket).scale(1.5f).mul(local);
  check(same(mounted,expected),"native world placement removed while mesh/script transform applied once");check(Math.abs(mounted.determinant()+Math.pow(.6,3))<.001,"phone world size and native reflection preserved");check(Math.abs(Math.abs(correction.determinant())-1)<.001,"correction preserves existing world bounds radius");
  var rows=packet(source,2);var saved=rows.clone();int[] flags={71,15},palette={-1,-1},shadow={-1,-1};var center=correction.transformPosition(new Vector3f(1,2,3));check(NativeHeldMount.apply(rows,flags,palette,shadow,1,2,correction)==1,"only requested appended row committed");check(Arrays.equals(Arrays.copyOf(rows,68),Arrays.copyOf(saved,68)),"original actor/native held row untouched");check(new Matrix4f().set(Arrays.copyOfRange(rows,68,84)).equals(expected,.0002f),"serialized appended matrix matches socket math");check(Arrays.equals(Arrays.copyOfRange(rows,68,84),Arrays.copyOfRange(rows,104,120)),"previous matrix refreshed to same newly appended pose");check(new Vector3f(rows[92],rows[93],rows[94]).equals(center,.0002f)&&rows[95]==saved[95],"bound center follows correction and radius stays native");check(flags[0]==71&&flags[1]==7,"native row flags untouched, new history flag reset");check(rows[84]==saved[84]&&rows[96]==saved[96]&&rows[120]==saved[120],"native material/UV/light payload preserved");
  rejects(()->NativeHeldMount.socket(array(new Matrix4f().scale(1,2,1)),pp),"nonuniform skeletal scale unsupported");rejects(()->NativeHeldMount.socket(array(new Matrix4f().m10(.1f)),pp),"sheared socket unsupported");rejects(()->NativeHeldMount.socket(array(new Matrix4f().zero()),pp),"singular socket unsupported");rejects(()->NativeHeldMount.socket(array(new Matrix4f().m00(Float.NaN)),pp),"nonfinite socket unsupported");rejects(()->NativeHeldMount.correction(aa,pp,array(new Matrix4f())),"unproven world source placement rejected");
  var atomic=packet(source,3);atomic[2*68+52]=Float.NaN;var before=atomic.clone();rejects(()->NativeHeldMount.apply(atomic,new int[3],new int[]{-1,-1,-1},new int[]{-1,-1,-1},1,3,correction),"later invalid native payload rejects whole append packet");check(Arrays.equals(atomic,before),"failed packet leaves all rows unchanged");rejects(()->NativeHeldMount.apply(packet(source,2),new int[2],new int[]{-1,0},shadow,1,2,correction),"skinned palette cannot be remounted");rejects(()->NativeHeldMount.apply(packet(source,2),new int[2],palette,new int[]{-1,0},1,2,correction),"shadow skin cannot be remounted");rejects(()->NativeHeldMount.apply(packet(source,6),new int[6],new int[]{-1,-1,-1,-1,-1,-1},new int[]{-1,-1,-1,-1,-1,-1},0,6,correction),"bounded append budget enforced");
 }
 public static void main(String[] args)throws Exception{
  math();var a=setup();a.capture();a.output[0].translation(99,99,99);NativeHeldFallback.render(a.frame);check(a.calls==1&&a.discards==0,"successful producer receipt remounted once");check(NativeHeldFallback.status().contains("Prop2"),"left physical hand uses Prop2");NativeHeldFallback.render(a.frame);check(a.calls==1,"anchor cannot be replayed");check(a.drawer.values()[68+12]==8.5f,"Prop copied after successful native capture rather than later shared mutation");
  a=setup();NativeHeldFallback.begin(a.frame,new Object(),a.actor);NativeHeldFallback.fingers(a.skin,a.output);a.output[0].translation(8,9,10);a.receipt=System.nanoTime();NativeHeldFallback.end(null);NativeHeldFallback.render(a.frame);check(a.drawer.values()[80]==-2f,"native Prop update after fingers is observed at capture exit");
  a=setup();NativeHeldFallback.begin(a.frame,new Object(),a.actor);NativeHeldFallback.fingers(a.skin,a.output);NativeHeldFallback.end(null);NativeHeldFallback.render(a.frame);check(a.calls==0,"unchanged native posedAt supplies no successful capture receipt");
  a=setup();NativeHeldFallback.begin(a.frame,new Object(),a.actor);NativeHeldFallback.fingers(a.skin,a.output);a.receipt=System.nanoTime();NativeHeldFallback.end(new IllegalStateException());NativeHeldFallback.render(a.frame);check(a.calls==0,"failed native capture cannot render");
  a=setup();NativeHeldFallback.begin(a.frame,new Object(),a.actor);NativeHeldFallback.fingers(a.skin,a.output);NativeHeldFallback.fingers(new Object(),a.output);NativeHeldFallback.fingers(a.skin,a.output);a.receipt=System.nanoTime();NativeHeldFallback.end(null);NativeHeldFallback.render(a.frame);check(a.calls==0,"mismatched bone scope permanently invalidated");
  a=setup();a.capture();a.current=false;NativeHeldFallback.render(a.frame);check(a.calls==0,"stale actor/input/scene/mesh state rejected before producer");
  a=setup();a.capture();a.eligible=false;NativeHeldFallback.render(a.frame);check(a.calls==0,"existing native held model/weapon/action priority prevents fallback producer");
  a=setup();a.capture();a.ready=false;NativeHeldFallback.render(a.frame);check(a.calls==1&&a.drawer==null&&NativeHeldFallback.status().contains("not ready"),"original loading or absent model never fabricated");
  a=setup();a.capture();a.validDrawer=false;NativeHeldFallback.render(a.frame);check(a.discards==1&&NativeHeldFallback.status().contains("rejected"),"changed native receipt discards only appended rows");
  a=setup();a.capture();NativeHeldFallback.configureForTest(false);NativeHeldFallback.configureForTest(true);NativeHeldFallback.render(a.frame);check(a.calls==0,"Off/On retires capture epoch");
  a=setup();NativeHeldFallback.begin(a.frame,new Object(),a.actor);NativeHeldFallback.configureForTest(false);NativeHeldFallback.begin(a.frame,new Object(),a.actor);NativeHeldFallback.fingers(a.skin,a.output);NativeHeldFallback.end(null);NativeHeldFallback.configureForTest(true);NativeHeldFallback.fingers(a.skin,a.output);a.receipt=System.nanoTime();NativeHeldFallback.end(null);NativeHeldFallback.render(a.frame);check(a.calls==0,"nested Off capture never borrows outer pose after reenable");
  a=setup();NativeHeldFallback.begin(a.frame,new Object(),a.actor);NativeHeldFallback.fingers(a.skin,a.output);NativeHeldFallback.begin(new Object(),new Object(),a.actor);NativeHeldFallback.fingers(new Object(),new Matrix4f[0]);NativeHeldFallback.end(null);a.receipt=System.nanoTime();NativeHeldFallback.end(null);NativeHeldFallback.render(a.frame);check(a.calls==1,"unsupported nested actor capture restores outer valid scope");
  a=setup();a.capture();var other=a;var thread=new Thread(()->NativeHeldFallback.render(other.frame));thread.start();thread.join();check(a.calls==0,"different thread cannot consume native capture packet");
  a=setup();a.capture();NativeHeldFallback.render(new Object());check(a.calls==0,"other frame cannot borrow current anchor");NativeHeldFallback.render(a.frame);check(a.calls==1,"exact frame retains original anchor");
  NativeHeldFallback.configureForTest(false);check(!NativeHeldFallback.enabled(),"fallback remains opt-in and safely Off");System.out.println("Native held fallback: "+checks+" checks passed; authored producer and matrices, no game or XR entry execution");
 }
}
